function buildAgentUserInputContent(message2, attachments) {
  const content = [{ type: "input_text", text: message2 }];
  for (const attachment of attachments) {
    content.push({ type: "input_text", text: "Attachment reference ID: " + attachment.id + ". File name: " + attachment.name + ". Type: " + attachment.kind + ". Use this exact attachment ID if a workspace tool needs to act on this file." });
    if (attachment.kind === "image") {
      content.push({ type: "input_image", image_url: attachment.dataUrl, detail: "high" });
    } else if (attachment.kind === "pdf") {
      content.push({ type: "input_file", filename: attachment.name, file_data: attachment.dataUrl });
    } else if (attachment.kind === "spreadsheet") {
      content.push({ type: "input_text", text: "Attached spreadsheet or records file: " + attachment.name + ". Worksheet: " + (attachment.sheetName || "JSON records") + ". Total data rows: " + (attachment.rows?.length || 0) + ". Column names and a sample of the first 20 rows follow. The complete parsed rows are available to the lead-import tool if the user asks to store them.\n" + JSON.stringify((attachment.rows || []).slice(0, 20), null, 2).slice(0, 18e3) });
    } else if (attachment.text) {
      content.push({ type: "input_text", text: "Attached text file: " + attachment.name + "\n" + attachment.text });
    }
  }
  return content;
}
