  const conversationEmailRequest = /\b(conversation|unified inbox|reply|replies|follow[- ]?up|inbox)\b.{0,50}\b(email|template|design)\b/i.test(message2) || /\b(email|template|design)\b.{0,50}\b(conversation|unified inbox|reply|follow[- ]?up)\b/i.test(message2);
  const explicitTemplateKind = whatsappRequest || campaignEmailRequest || conversationEmailRequest;
