      const attachmentNote = Array.isArray(item.attachments) && item.attachments.length ? "\n[Previous attachments: " + item.attachments.map((file) => "id=" + String(file.id || "") + ", " + String(file.name || "file") + " (" + String(file.kind || file.mimeType || "file") + ")" + (file.rowCount ? ", " + file.rowCount + " rows" : "") + (file.previewText ? ": " + String(file.previewText).slice(0, 5e3) : "")).join(" | ") + "]" : "";
